) as v(state_code, name, authority_type, address, contact_email, contact_phone, website_url)
join public.malaysia_states s on s.code = v.state_code
on conflict (state_id, name) do update set
  authority_type = excluded.authority_type,
  address = excluded.address,
  contact_email = excluded.contact_email,
  contact_phone = excluded.contact_phone,
  website_url = excluded.website_url,
  directory_source_url = excluded.directory_source_url,
  directory_updated_at = excluded.directory_updated_at;

insert into public.responsible_authorities (
  local_authority_id, name, authority_type, contact_email, contact_phone
)
select la.id, la.name, 'local_council', la.contact_email, la.contact_phone
from public.local_authorities la
where la.directory_source_url = 'https://archive.data.gov.my/data/dataset/0888d4b0-b9fa-4a2e-a7d8-2b6370e041eb/resource/996cab73-7c8c-4c91-a48a-fb9c1ce017f5/download/_202303021254050_2021_jkt_40-senarai-maklumat-perhubungan-pihak-berkuasa-tempatan-dan-agensi-dib.csv'
on conflict (local_authority_id, name) do update set
  contact_email = excluded.contact_email,
  contact_phone = excluded.contact_phone,
  is_active = true;

-- No township polygon is created here. A polygon requires a separate official
-- service-boundary source and review before it can enable automatic routing.
